+func printTrailResumeCommands(w io.Writer, commands []string) {
+	if len(commands) == 0 {
+		return
+	}
+	fmt.Fprintln(w, "  Commands:")
+	for _, command := range commands {
+		fmt.Fprintf(w, "    %s\n", command)
+	}
+}
