+func findTrailResumeSession(sessions []trailResumeSessionContext, sessionID string) (trailResumeSessionContext, bool) {
+	for _, session := range sessions {
+		if session.SessionID == sessionID {
+			return session, true
+		}
+	}
+	return trailResumeSessionContext{}, false
+}
+
+func runTrailResumePicker(ctx context.Context, cmd *cobra.Command, branch string, sessions []trailResumeSessionContext, force bool) error {
+	if otherPath, ok := branchCheckedOutElsewhere(ctx, branch); ok {
+		fmt.Fprintf(cmd.OutOrStdout(), "Branch %q is already checked out in another worktree:\n", branch)
+		fmt.Fprintf(cmd.OutOrStdout(), "  %s\n\n", otherPath)
+		fmt.Fprintf(cmd.OutOrStdout(), "Resume from that worktree with:\n")
+		fmt.Fprintf(cmd.OutOrStdout(), "  cd %s && entire trail resume %s\n", shellQuote(otherPath), shellArg(branch))
+		return nil
+	}
+
+	options := make([]huh.Option[string], 0, len(sessions)+2)
+	options = append(options, huh.NewOption("Latest checkpoint on branch", trailResumePickerLatest))
+	for _, session := range sessions {
+		options = append(options, huh.NewOption(trailResumeSessionOptionLabel(session), session.SessionID))
+	}
+	options = append(options, huh.NewOption("Cancel", resumePickerCancel))
+
+	selected := trailResumePickerLatest
+	form := NewAccessibleForm(
+		huh.NewGroup(
+			huh.NewSelect[string]().
+				Title("Resume this trail").
+				Description("Choose a known local session or resume the latest checkpoint on the branch.").
+				Options(options...).
+				Value(&selected),
+		),
+	)
+	if err := form.RunWithContext(ctx); err != nil {
+		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
+			return nil
+		}
+		return fmt.Errorf("selection failed: %w", err)
+	}
+	if selected == "" || selected == resumePickerCancel {
+		fmt.Fprintln(cmd.OutOrStdout(), "Resume cancelled.")
+		return nil
+	}
+	if selected == trailResumePickerLatest {
+		return runResume(ctx, cmd, branch, force)
+	}
+	sessionCtx, ok := findTrailResumeSession(sessions, selected)
+	if !ok {
+		return fmt.Errorf("invalid selection %q", selected)
+	}
+	return resumeSessionOnBranch(ctx, cmd, branch, id.CheckpointID(sessionCtx.CheckpointID), force)
+}
+
+func trailResumeSessionOptionLabel(session trailResumeSessionContext) string {
+	prompt := strings.TrimSpace(session.LastPrompt)
+	if prompt == "" {
+		prompt = "(no prompt recorded)"
+	} else {
+		prompt = stringutil.TruncateRunes(stringutil.CollapseWhitespace(prompt), 50, "...")
+	}
+	agent := session.Agent
+	if agent == "" {
+		agent = "(unknown agent)"
+	}
+	when := "-"
+	if !session.LastActive.IsZero() {
+		when = timeAgo(session.LastActive)
+	}
+	return fmt.Sprintf("%s · %s · %s · last active %s", session.SessionID, prompt, agent, when)
+}
