	}

	startTime, err := time.Parse(time.RFC3339Nano, meta.Timestamp)
	if err != nil {
		return time.Time{}, fmt.Errorf("parse session_meta timestamp %q: %w", meta.Timestamp, err)
	}
	return startTime, nil
}

