func continueTrailRestoredSessions(ctx context.Context, cmd *cobra.Command, sessions []strategy.RestoredSession, preferredSessionID string) error {
	w := cmd.OutOrStdout()
	if len(sessions) == 0 {
		return nil
	}

	if preferredSessionID != "" {
		session, ok := findTrailRestoredSession(sessions, preferredSessionID)
		if !ok {
			return fmt.Errorf("session %q was not found in the restored checkpoint", preferredSessionID)
		}
		if !interactive.CanPromptInteractively() {
			return displayTrailRestoredSessions(w, []strategy.RestoredSession{session})
		}
		printTrailRestoredSessionSummary(w, []strategy.RestoredSession{session})
		return launchTrailRestoredSession(ctx, w, session)
	}

	if !interactive.CanPromptInteractively() {
		return displayTrailRestoredSessions(w, sessions)
	}

	printTrailRestoredSessionSummary(w, sessions)
	if len(sessions) == 1 {
		return launchTrailRestoredSession(ctx, w, sessions[0])
	}

	selected, ok, err := promptTrailRestoredSession(ctx, w, sessions)
	if err != nil || !ok {
		return err
	}
	return launchTrailRestoredSession(ctx, w, selected)
}

func printTrailRestoredSessionSummary(w io.Writer, sessions []strategy.RestoredSession) {
	if len(sessions) > 1 {
		fmt.Fprintf(w, "\n✓ Restored %d checkpoint sessions.\n", len(sessions))
	} else if len(sessions) == 1 {
		fmt.Fprintf(w, "✓ Restored checkpoint session %s.\n", sessions[0].SessionID)
	}
	if len(sessions) > 0 && trailRestoredSessionsAreAllReviewOrInvestigation(sessions) {
		fmt.Fprintln(w, "  Only review/investigation checkpoint sessions were found; these are transcript logs and may not appear as trail UI sessions.")
	}
}

func displayTrailRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
	if len(sessions) == 0 {
		return nil
	}
	choices := buildTrailResumeRestoredSessionChoices(sessions)
	printTrailRestoredSessionSummary(w, sessions)
	if len(choices) > 1 {
		fmt.Fprintln(w, "To continue:")
	} else {
		fmt.Fprintln(w, "\nTo continue this checkpoint session:")
	}

	isMulti := len(choices) > 1
	for i, choice := range choices {
		sessionAgent, err := strategy.ResolveAgentForRewind(choice.Session.Agent)
		if err != nil {
			return fmt.Errorf("failed to resolve agent for session %s: %w", choice.SessionID, err)
		}
		printSessionCommand(w, sessionAgent.FormatResumeCommand(choice.SessionID), trailRestoredSessionPrompt(choice.Session), isMulti, i == len(choices)-1)
	}
	return nil
}

func resolveTrailResumeSessionContexts(ctx context.Context, branch string) ([]trailResumeSessionContext, error) {
	sessions, err := resolveTrailCheckpointSessions(ctx, branch)
	if err == nil && len(sessions) > 0 {
		return sessions, nil
	}

	items, localErr := resolveTrailResumeSessions(ctx, branch)
	if localErr != nil {
		if err != nil {
			return nil, err
		}
		return nil
	}
	fmt.Fprintf(w, "\nLaunching: %s\n", resumeCmd)
	if err := cmd.Run(); err != nil {
		return fmt.Errorf("resume command failed: %w", err)
	}
	return nil
}

func runTrailResumePicker(ctx context.Context, cmd *cobra.Command, branch string, sessions []trailResumeSessionContext, force bool) error {
	if otherPath, ok := branchCheckedOutElsewhere(ctx, branch); ok {
		fmt.Fprintf(cmd.OutOrStdout(), "Branch %q is already checked out in another worktree:\n", branch)
		fmt.Fprintf(cmd.OutOrStdout(), "  %s\n\n", otherPath)
		fmt.Fprintf(cmd.OutOrStdout(), "Resume from that worktree with:\n")
		fmt.Fprintf(cmd.OutOrStdout(), "  cd %s && entire trail resume %s\n", shellQuote(otherPath), shellArg(branch))
		return nil
	}

	options := make([]huh.Option[string], 0, len(sessions)+1)
	for _, session := range sessions {
		options = append(options, huh.NewOption(trailResumeSessionOptionLabel(session), session.SessionID))
	}
	options = append(options, huh.NewOption("Cancel", resumePickerCancel))

	selected := sessions[0].SessionID
	form := NewAccessibleForm(
		huh.NewGroup(
			huh.NewSelect[string]().
				Title("Choose a checkpoint session to resume").
				Description("These sessions are recorded in the trail branch checkpoint.").
				Options(options...).
				Value(&selected),
		),
	)
	if err := form.RunWithContext(ctx); err != nil {
		if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
			Prompt:    "Review this branch for regressions.",
		},
	})

	text := out.String()
	for _, want := range []string{
		"Restored 2 checkpoint sessions",
		"Only review/investigation checkpoint sessions were found",
		"may not appear as trail UI sessions",
	} {
		if !strings.Contains(text, want) {
			t.Fatalf("summary missing %q:\n%s", want, text)
		}
	}
}

