	fmt.Fprintf(w, "  Updated: %s\n", m.UpdatedAt.Format("2006-01-02T15:04:05Z07:00"))
	if strings.TrimSpace(bodyText) != "" {
		fmt.Fprintf(w, "\nDescription:\n%s\n", bodyText)
	}
